public class AutoboxingPitfalls {
    public static void main(String[] args) {
        // Pitfall 1: The Integer Cache Identity Trap
        Integer a1 = 127;
        Integer a2 = 127;
        System.out.println(a1 == a2); // Prints true (cached reference)

        Integer b1 = 128;
        Integer b2 = 128;
        System.out.println(b1 == b2); // Prints false (different heap objects!)
        System.out.println(b1.equals(b2)); // Prints true (correct value comparison)

        // Pitfall 2: Ternary Operator NullPointerException
        Integer nullableCount = null;
        boolean condition = true;
        // Throws NullPointerException because the compiler unboxes nullableCount to match the primitive 0
        int result = condition ? nullableCount : 0;

        // Pitfall 3: Massive GC Pressure in Loops
        Long sum = 0L; // Boxed wrapper
        for (long i = 0; i < 1_000_000; i++) {
            sum += i; // Unboxes sum, adds i, boxes result back into a new Long object!
        }
        // This loop creates 1,000,000 short-lived Long objects on the heap, thrashing the GC.
    }
}
